      "id": "native-instruments-komplete-kontrol-a25-mug6mnbf",
      "name": "Native Instruments Komplete Kontrol A25",
      "shortName": "Native Instruments Komplete Kontrol A25",
      "brand": "Native Instruments",
      "category": "MIDI Controllers",
      "section": "pro-audio",
      "subcategory": "",
      "price": 20810,
      "originalPrice": 20810,
