      html += '<label class="ak-filter-checkbox-item ' + (isChecked ? "active" : "") + '" data-brand="' + b.toLowerCase() + '"><input type="radio" name="akStoreBrandRadio" class="ak-brand-check" value="' + b + '" ' + (isChecked ? "checked" : "") + '><span class="ak-checkbox-custom ak-radio-custom"></span><span class="ak-filter-label">' + b + '</span><span class="ak-filter-count">(' + brandCounts[b] + ")</span></label>";
